{* Code generated by authfly/codegen from specs/widgets/sign-up.def.ts. DO NOT EDIT.
   Authfly sign-up on UI8Kit 3 primitives: name, username at the mail domain, password, terms. Props identical to xgen. *}
{import '../authfly/components.latte'}
{var $id = $p['id'] ?? ''}{var $l = $p['labels'] ?? []}{var $error = $p['error'] ?? ''}
{var $formError = $error ? $id . '-error' : null}
{var $lm = ['aria-labelledby' => ($p['landmarkLabel'] ?? '') ? null : $id . '-title', 'aria-label' => $p['landmarkLabel'] ?? null]}
{capture $c5}
{include head, $id, $p['title'] ?? '', $p['text'] ?? ''}
{include messages, $id, $error, $p['info'] ?? ''}
{capture $c3}{include hidden, 'csrf', $p['csrf'] ?? ''}
{include field, ['label' => $l['name'] ?? '', 'for' => $id . '-name', 'formError' => $formError, 'input' => ['type' => 'text', 'name' => 'name', 'attrs' => ['autocomplete' => 'name']]]}
{capture $c1}{if $l['domain'] ?? ''}{include text, 'span', afText('muted'), ['id' => $id . '-domain', 'data-testid' => 'domain'], afEsc($l['domain'] ?? '')}{/if}{/capture}
{include field, ['label' => $l['username'] ?? '', 'for' => $id . '-username', 'formError' => $formError, 'describe' => ($l['domain'] ?? '') ? $id . '-domain' : null, 'suffix' => (string) $c1, 'input' => ['type' => 'text', 'name' => 'username', 'required' => true, 'attrs' => ['autocomplete' => 'username']]]}
{include field, ['label' => $l['password'] ?? '', 'for' => $id . '-password', 'hint' => $l['hint'] ?? '', 'formError' => $formError, 'input' => ['type' => 'password', 'name' => 'password', 'required' => true, 'attrs' => ['autocomplete' => 'new-password']]]}
{if ($p['terms'] ?? 'show') === 'show'}
{capture $c2}{include '../ui/checkbox/Checkbox.latte', name: 'terms', required: true, id: $id . '-terms', ariaDescribedBy: $formError, ariaInvalid: $formError ? 'true' : null, class: afSkin('checkbox')}{include '../ui/label/Label.latte', htmlFor: $id . '-terms', class: afSkin('label', 'font-normal'), children: (string) afEsc($l['terms'] ?? '')}{/capture}
{include group, '2', '', '', 'w-fit', [], $c2}
{/if}
{include button, '', 'submit', afSkin('button', 'default', 'w-full'), ['data-testid' => 'submit'], afEsc($l['submit'] ?? '')}{/capture}
{include form, $p['action'] ?? '', '', ['data-testid' => 'authfly-form'], $c3}
{if $l['signinLink'] ?? ''}
{capture $c4}{$l['signinText'] ?? ''} {include link, $l['signinHref'] ?? '', afSkin('link'), 'signin-link', $l['signinLink'] ?? ''}{/capture}
{include text, '', afText('muted'), [], $c4}
{/if}
{/capture}
{include card, afSkin('widgetCard'), ['data-testid' => 'authfly-sign-up'] + $lm, $c5}
